import React, { FC } from 'react';
import cls from 'classnames';
import { usePrefixCls } from '../../__builtins__';
import { FormStepDecoratorProps } from '../types';

export const DefaultFormStepDecorator: FC<FormStepDecoratorProps> = props => {
  const {
    style,
    className = '',
    title,
    arcoSteps,
    steps,
    headerSlot,
    topSlot,
    footerSlot,
    buttonsSlot,
    residentContentSlot,
    children,
  } = props || {};
  const prefixCls = usePrefixCls('form-step', props);
  return (
    <div className={cls(prefixCls, className)} style={style}>
      {title ? <div className={`${prefixCls}-title`}>{title}</div> : null}
      {headerSlot ? <div className={`${prefixCls}-header`}>{headerSlot}</div> : null}
      {topSlot ? <div className={`${prefixCls}-top`}>{topSlot}</div> : null}
      {arcoSteps ? <div className={`${prefixCls}-arco-steps`}>{arcoSteps}</div> : null}

      <div className={`${prefixCls}-step-container`}>
        {steps}
        {children}
      </div>
      {residentContentSlot ? <div className={`${prefixCls}-resident-content`}>{residentContentSlot}</div> : null}
      {footerSlot ? <div className={`${prefixCls}-footer`}>{footerSlot}</div> : null}
      {!footerSlot && buttonsSlot ? <div className={`${prefixCls}-buttons`}>{buttonsSlot}</div> : null}
    </div>
  );
};
